import java.util.LinkedHashMap;
import java.util.Map;

public class Main {
  public static void main(String[] args) {
      // Un LinkedHashMap garantiza el orden de inserción
      Map<String, Integer> serie = new LinkedHashMap<>();
      serie.put("x", 1);
      serie.put("y", 7);
      serie.put("z", 2);

      System.out.println(serie);
  }
}
